export async function addVault(path: string): Promise<Vault[]> {
    const store = await loadStore();
    const vaults = (await store.get<Vault[]>("vaults")) ?? [];

    if (vaults.some((v) => v.path === path)) {
        return vaults;
    }

    // regex for name
    const name = path.split(/[\\/]/).pop() ?? path;
    const updated_vaults = [...vaults, { path, name }];

    await store.set("vaults", updated_vaults);

    return updated_vaults;
}

