            filePath === entry.path ||
            (entry.isDirectory && filePath?.startsWith(entry.path + "/"))
        ) {
            setContent("");
            setFileName("");
            setFilePath(null);
        }

        if (activeVault) setEntries(await readDir(activeVault));
    } catch (err) {
        alert(String(err));
    }
