async function getAvailableFileName(dir: string, ext: string): Promise<string> {
    const siblings = await readDirShallow(dir);
    const existingNames = new Set(siblings.map((e) => e.name));

    if (!existingNames.has(`Untitled${ext}`)) {
        return `Untitled${ext}`;
    }

    let i = 1;
    while (existingNames.has(`Untitled ${i}${ext}`)) {
        i++;
    }

    return `Untitled ${i}${ext}`;
}

