function buildDecorations(view: EditorView): DecorationSet {
    const pending: PendingDecoration[] = [];
    const cursorLine = view.state.doc.lineAt(
        view.state.selection.main.head,
    ).number;

    for (const { from, to } of view.visibleRanges) {
        syntaxTree(view.state).iterate({
            from,
            to,
            enter: (node) => {
                const nodeLine = view.state.doc.lineAt(node.from).number;
                const cursorInLine = nodeLine === cursorLine;

                switch (node.name) {
                    case "ATXHeading1":
                    case "ATXHeading2":
                    case "ATXHeading3":
                    case "ATXHeading4":
                    case "ATXHeading5":
                    case "ATXHeading6": {
                        const level = Number(node.name.slice(-1));
                        pending.push({
                            from: node.from,
                            to: node.to,
                            decoration: headingMarks[level],
                        });
                        break;
                    }
                    case "HeaderMark": {
                        if (!cursorInLine) {
                            const line = view.state.doc.lineAt(node.from);
                            const spaceEnd = Math.min(node.to + 1, line.to);
                            pending.push({
                                from: node.from,
                                to: spaceEnd,
                                decoration: hiddenRange,
                            });
                        }
                        break;
                    }
                    case "StrongEmphasis": {
                        pending.push({
                            from: node.from,
                            to: node.to,
                            decoration: boldMark,
                        });
                        break;
                    }
                    case "Emphasis": {
                        pending.push({
                            from: node.from,
                            to: node.to,
                            decoration: italicMark,
                        });
                        break;
                    }
                    case "EmphasisMark": {
                        if (!cursorInLine) {
                            pending.push({
                                from: node.from,
                                to: node.to,
                                decoration: hiddenRange,
                            });
                        }
                        break;
                    }
                    case "InlineCode": {
                        pending.push({
                            from: node.from,
                            to: node.to,
                            decoration: codeMark,
                        });
                        break;
                    }
                    case "CodeMark": {
                        if (!cursorInLine) {
                            pending.push({
                                from: node.from,
                                to: node.to,
                                decoration: hiddenRange,
                            });
                        }
                        break;
                    }
                }
            },
        });
    }

    // sort by ascending order to replace widgets before marks
    pending.sort((a, b) => a.from - b.from || a.to - a.from - (b.to - b.from));

    const builder = new RangeSetBuilder<Decoration>();
    for (const { from, to, decoration } of pending) {
        builder.add(from, to, decoration);
    }

    return builder.finish();
}

