export function buildMarkdownTheme(config: MarkdownStyleConfig) {
    const headingStyles: Record<
        string,
        { fontWeight: string; fontSize: string }
    > = {};
    for (let l = 1; l <= 6; l++) {
        headingStyles[`.cm-live-heading-${l}`] = {
            fontWeight: config.headingWeight,
            fontSize: `${config.headingScales[l - 1]}em`,
        };
    }

    return EditorView.theme({
        ...headingStyles,
        ".cm-live-bold": { fontWeight: config.boldWeight },
        ".cm-live-italic": { fontStyle: config.italicStyle },
        ".cm-live-code": {
            fontFamily: config.codeFont,
            backgroundColor: config.codeBackground,
            borderRadius: config.codeRadius,
            padding: config.codePadding,
        },
    });
}

